def listing_picker_keyboard(kind, make="", subcategory=""):
    """Open structured pickers inline so they never replace the admin reply keyboard."""
    parsed = urllib.parse.urlsplit(str(MINI_APP_URL or "").strip())
    picker_url = urllib.parse.urlunsplit((parsed.scheme, parsed.netloc, "/listing-picker", "", ""))
    query = {"kind": kind}
    if make:
        query["make"] = make
    if subcategory:
        query["subcategory"] = subcategory
    picker_url += "?" + urllib.parse.urlencode(query)
    labels = {"make":"🚘 Выбрать марку","model":"🚘 Выбрать модель","year":"📅 Выбрать год","mileage":"🛣 Выбрать пробег","city":"📍 Выбрать город","color":"🎨 Выбрать цвет","drivetrain":"⚙️ Выбрать привод","engine_volume":"🔧 Выбрать объём двигателя","fuel_type":"⛽ Выбрать тип топлива"}
    return {"inline_keyboard":[[{"text":labels.get(kind,"Выбрать"),"web_app":{"url":picker_url}}]]}

def send_listing_picker(chat_id, title, kind, index=None, make=""):
    current_step = str(states[chat_id].get("step", ""))
    is_edit = current_step.startswith("edit_")
    if index is not None:
        states[chat_id]["step"] = f"edit_detail_{index}" if is_edit else f"detail_{index}"
    elif kind == "city":
        states[chat_id]["step"] = "edit_district" if is_edit else "district"
    listing_data = states[chat_id].get("data") or {}
    subcategory = str(listing_data.get("subcategory_key") or "") if kind in {"area", "tech_brand", "tech_model", "engine_volume", "fuel_type"} else ""
    states[chat_id]["listing_picker"] = {"kind":kind,"index":index,"make":make,"subcategory":subcategory,"is_edit":is_edit}
    return api("sendMessage", {"chat_id":chat_id,"text":title,"parse_mode":"HTML","reply_markup":listing_picker_keyboard(kind,make,subcategory)})


