def ask_detail(
    chat_id,
    index=0
):

    data = states[
        chat_id
    ]["data"]

    fields = category_fields(data)

    if index < len(fields):

        _, label = fields[
            index
        ]

        field_key = fields[index][0]
        prompt = f"<b>{index + 3} · {esc(label)}</b>\n\n"
        if field_key == "condition":
            prompt += "Выберите состояние товара:"
            send(chat_id, prompt, condition_choice_keyboard())
            states[chat_id]["step"] = f"detail_{index}"
        elif data.get("category_key") == "pets" and field_key in {"age", "gender"}:
            prompt += "Выберите подходящий вариант из списка."
            send(chat_id, prompt, pet_choice_keyboard(field_key, "petpick"))
            states[chat_id]["step"] = f"detail_{index}"
        elif data.get("category_key") == "auto" and data.get("subcategory_key") in {"cars", "suv"} and field_key == "make_model":
            send_auto_make_picker(chat_id, index)
        elif data.get("category_key") == "auto" and data.get("subcategory_key") in {"cars", "suv"} and field_key == "year":
            send_listing_picker(chat_id, "<b>📅 Выберите год выпуска</b>", "year", index)
        elif data.get("category_key") == "auto" and data.get("subcategory_key") in {"cars", "suv"} and field_key == "mileage":
            send_listing_picker(chat_id, "<b>🛣 Выберите пробег автомобиля</b>", "mileage", index)
        elif data.get("category_key") == "auto" and data.get("subcategory_key") in {"cars", "suv", "moto"} and field_key in {"color", "drivetrain", "engine_volume", "fuel_type"}:
            picker_titles = {
                "color": "<b>🎨 Выберите цвет</b>",
                "drivetrain": "<b>⚙️ Выберите привод</b>",
                "engine_volume": "<b>🔧 Выберите объём двигателя от 0 до 10 л</b>",
                "fuel_type": "<b>⛽ Выберите тип топлива</b>",
            }
            send_listing_picker(chat_id, picker_titles[field_key], field_key, index)
        elif data.get("category_key") == "realestate" and field_key in {"rooms", "floor"}:
            title = "количество комнат" if field_key == "rooms" else "этаж"
            send_listing_picker(chat_id, f"<b>🏠 Выберите {title}</b>", field_key, index)
        elif data.get("category_key") == "realestate" and field_key == "area":
            send_listing_picker(chat_id, "<b>📐 Выберите площадь объекта</b>", "area", index)
        elif data.get("category_key") == "tech" and field_key == "brand_model":
            send_listing_picker(chat_id, "<b>📱 Выберите производителя техники</b>", "tech_brand", index)
        elif data.get("category_key") == "tech" and field_key == "warranty":
            prompt += "Выберите наличие гарантии:"
            send(chat_id, prompt, [[{"text": "✅ Есть гарантия", "callback_data": "warrantypick_yes"}, {"text": "❌ Нет гарантии", "callback_data": "warrantypick_no"}]])
            states[chat_id]["step"] = f"detail_{index}"
        elif data.get("category_key") == "kids" and field_key == "age":
            send_listing_picker(chat_id, "<b>👶 Выберите возраст ребёнка</b>", "child_age", index)
        elif data.get("category_key") in {"work", "services"} and field_key == "experience":
            send_listing_picker(chat_id, "<b>⭐ Выберите опыт работы</b>", "experience", index)
        else:
            if data.get("category_key") == "realestate" and field_key == "area":
                prompt += "Введите только число в м². Например: 70 или 125."
            else:
                prompt += "Введите значение. Опечатки в известных названиях будут исправлены автоматически."
            ask(chat_id, f"detail_{index}", prompt)

    else:

        ask_price(
            chat_id
        )


