@app.get("/api/admin/stats")
def mini_app_admin_stats():
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(user):
        return jsonify({"error":"admin_only"}), 403
    try:
        days = int(request.args.get("days", "7"))
    except (TypeError, ValueError):
        days = 7
    if days not in (7, 30, 90):
        days = 7
    return jsonify(_admin_stats_payload(days))


@app.get("/api/admin/data")
def mini_app_admin_data():
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(user):
        return jsonify({"error":"admin_only"}), 403
    if not supabase_enabled():
        return jsonify({"error":"db_unavailable"}), 503

    kind = (request.args.get("kind") or "").strip().lower()
    if kind == "user":
        user_id = (request.args.get("id") or "").strip()
        if not user_id.isdigit():
            return jsonify({"error":"invalid_id"}), 400
        rows = supabase_request("GET", "users", params={
            "select":"*", "id":f"eq.{user_id}", "limit":"1"
        })
        if not isinstance(rows, list) or not rows:
            return jsonify({"error":"user_not_found"}), 404
        user_row = rows[0]
        listings = supabase_request("GET", "listings", params={
            "select":"id,title,status,price,currency,created_at", "user_id":f"eq.{user_id}",
            "order":"created_at.desc", "limit":"100"
        })
        return jsonify({"item":user_row, "listings":listings if isinstance(listings,list) else []})

    if kind == "listing":
        listing_id = (request.args.get("id") or "").strip()
        if not listing_id.isdigit():
            return jsonify({"error":"invalid_id"}), 400
        rows = supabase_request("GET", "listings", params={
            "select":"*", "id":f"eq.{listing_id}", "limit":"1"
        })
        if not isinstance(rows, list) or not rows:
            return jsonify({"error":"listing_not_found"}), 404
        item = dict(rows[0])
        # Prefer the event log for the admin-facing view count. This does not
        # mutate listings or change the publication flow; analytics stays optional.
        try:
            exact_views = _supabase_exact_count("mm_analytics_events", {
                "event_type":"eq.listing_view", "listing_id":f"eq.{listing_id}"
            })
            if exact_views is not None:
                item["views_count"] = exact_views
            else:
                view_events = supabase_request("GET", "mm_analytics_events", params={
                    "select":"id", "event_type":"eq.listing_view",
                    "listing_id":f"eq.{listing_id}", "limit":"100000"
                })
                if isinstance(view_events, list):
                    item["views_count"] = len(view_events)
        except Exception as error:
            print("MADLOBA LISTING VIEW COUNT ERROR:", repr(error))
        return jsonify({"item":item})

    if kind == "support":
        view = (request.args.get("view") or "active").strip().lower()
        if view not in {"active", "history"}:
            return jsonify({"error":"invalid_support_view"}), 400
        support_filters = {
            "status": "in.(new,in_progress)" if view == "active" else "eq.closed"
        }
        rows = supabase_request("GET", "mm_support_tickets", params={
            "select":"id,telegram_user_id,username,full_name,city,lang,topic,message,status,created_at,updated_at,handled_by",
            "order":"created_at.desc", "limit":"100", **support_filters
        })
        if rows is None:
            return jsonify({"error":"support_unavailable"}), 503
        return jsonify({"items": rows, "view": view})

    if kind == "reports":
        view = (request.args.get("view") or "active").strip().lower()
        if view not in {"active", "history"}:
            return jsonify({"error":"invalid_reports_view"}), 400
        report_filters = {
            "status": "in.(new,reviewing)" if view == "active" else "in.(dismissed,resolved)"
        }
        rows = supabase_request("GET", "mm_listing_reports", params={
            "select":"id,listing_id,listing_title,reporter_user_id,reason,details,status,admin_note,created_at,updated_at",
            "order":"created_at.desc", "limit":"100", **report_filters
        })
        if rows is None:
            return jsonify({"error":"reports_unavailable"}), 503
        return jsonify({"items": rows, "view": view})

    if kind in {"users", "listings"}:
        # Admin lists are always server-paginated. The dashboard preview requests
        # five rows; the full browser requests at most twenty rows per page.
        try:
            page = max(0, int(request.args.get("page", "0")))
            limit = int(request.args.get("limit", request.args.get("per_page", "5")))
        except (TypeError, ValueError):
            return jsonify({"error":"invalid_pagination"}), 400
        limit = max(1, min(limit, 20))
        offset = page * limit
        query = str(request.args.get("q") or "").strip()
        # Restrict search syntax so user input cannot alter PostgREST filter grammar.
        query = re.sub(r"[^\w\s@.+-]", "", query, flags=re.UNICODE)[:80].strip()
        filters = {}
        if kind == "listings":
            # The normal list remains focused on live work; archived listings have
            # their own explicit view so an admin can locate and restore them.
            listing_view = str(request.args.get("view") or "active").strip().lower()
            if listing_view == "archived":
                filters["status"] = "eq.archived"
            elif listing_view == "active":
                filters["status"] = "in.(published,pending,pending_moderation,moderation,review)"
            else:
                return jsonify({"error":"invalid_listings_view"}), 400
        if query:
            safe = query.replace("\\", "")
            if kind == "users":
                terms = [f"username.ilike.*{safe}*", f"first_name.ilike.*{safe}*", f"last_name.ilike.*{safe}*"]
                if safe.isdigit():
                    terms.extend([f"id.eq.{safe}", f"telegram_id.eq.{safe}"])
                filters["or"] = "(" + ",".join(terms) + ")"
            else:
                terms = [f"title.ilike.*{safe}*", f"address.ilike.*{safe}*"]
                if safe.isdigit():
                    terms.append(f"id.eq.{safe}")
                filters["or"] = "(" + ",".join(terms) + ")"

        table = "users" if kind == "users" else "listings"
        select = "id,telegram_id,username,first_name,last_name,created_at" if kind == "users" else "id,user_id,title,status,price,currency,address,created_at"
        count = _supabase_exact_count(table, filters)
        params = {"select":select, "order":"id.desc" if kind == "users" else "created_at.desc,id.desc",
                  "limit":str(limit), "offset":str(offset)}
        params.update(filters)
        rows = supabase_request("GET", table, params=params)
        if rows is None:
            return jsonify({"error":f"{kind}_unavailable"}), 503

        if kind == "users":
            return jsonify({"items":rows, "total":count, "page":page, "per_page":limit})

        user_ids = {str(row.get("user_id")) for row in rows if row.get("user_id")}
        owner_map = {}
        if user_ids:
            owners = supabase_request("GET", "users", params={
                "select":"id,telegram_id", "id":f"in.({','.join(user_ids)})", "limit":"100"
            })
            if isinstance(owners, list):
                owner_map = {str(owner.get("id")): owner.get("telegram_id") for owner in owners}
        items = []
        for row in rows:
            item = dict(row)
            item["telegram_id"] = owner_map.get(str(row.get("user_id")), "")
            items.append(item)
        return jsonify({"items":items, "total":count, "page":page, "per_page":limit})

    return jsonify({"error":"invalid_kind"}), 400


@app.get("/api/admin/moderation")
def mini_app_admin_moderation():
    """Read-only Mini App view of the existing durable Telegram moderation queue."""
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(user):
        return jsonify({"error":"admin_only"}), 403
    if not supabase_enabled():
        return jsonify({"error":"db_unavailable"}), 503

    try:
        page = max(0, int(request.args.get("page", "0")))
        per_page = int(request.args.get("per_page", "10"))
    except (TypeError, ValueError):
        return jsonify({"error":"invalid_pagination"}), 400
    per_page = max(1, min(per_page, 20))

    try:
        pending = load_pending_moderation_queue()
    except Exception as error:
        print("ADMIN MODERATION QUEUE LOAD ERROR:", repr(error))
        return jsonify({"error":"moderation_queue_unavailable"}), 503

    total = len(pending)
    start = page * per_page
    items = []
    for request_id, payload in pending[start:start + per_page]:
        data = payload.get("data") if isinstance(payload, dict) else {}
        data = data if isinstance(data, dict) else {}
        photos = data.get("photos") or []
        if not isinstance(photos, list):
            photos = []
        try:
            title = make_title(data)
        except Exception:
            title = ""
        try:
            price = price_text(data)
        except Exception:
            price = ""
        items.append({
            "request_id": int(request_id),
            "user_chat_id": str(payload.get("user_chat_id") or ""),
            "created_at": str(payload.get("created_at") or ""),
            "title": str(title or data.get("title") or "Объявление")[:180],
            "category": str(data.get("category") or "")[:80],
            "type": str(data.get("type") or "")[:80],
            "subcategory": str(data.get("subcategory") or "")[:100],
            "district": str(data.get("district") or "")[:120],
            "price": str(price or "")[:100],
            "description": str(data.get("description") or "")[:500],
            "photos_count": len(photos),
        })
    return jsonify({
        "items": items,
        "total": total,
        "page": page,
        "per_page": per_page,
        "source": "telegram_runtime_moderation_queue",
        "queue_cap": 500,
    })


@app.get("/api/admin/moderation/<int:request_id>")
def mini_app_admin_moderation_detail(request_id):
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(user):
        return jsonify({"error":"admin_only"}), 403
    pending = dict(load_pending_moderation_queue())
    item = pending.get(int(request_id))
    if not isinstance(item, dict):
        return jsonify({"error":"request_not_found"}), 404
    data = item.get("data") if isinstance(item.get("data"), dict) else {}
    photos = data.get("photos") or []
    if not isinstance(photos, list):
        photos = []
    safe_photos = [
        f"/api/admin/moderation/{int(request_id)}/photo/{index}"
        for index, photo in enumerate(photos[:8])
        if isinstance(photo, str) and photo.strip()
    ]
    try:
        title = make_title(data)
    except Exception:
        title = ""
    try:
        price = price_text(data)
    except Exception:
        price = ""
    return jsonify({
        "item": {
            "request_id": int(request_id),
            "user_chat_id": str(item.get("user_chat_id") or ""),
            "created_at": str(item.get("created_at") or ""),
            "title": str(title or data.get("title") or "Объявление")[:180],
            "category": str(data.get("category") or "")[:80],
            "type": str(data.get("type") or "")[:80],
            "subcategory": str(data.get("subcategory") or "")[:100],
            "district": str(data.get("district") or "")[:120],
            "price": str(price or "")[:100],
            "description": str(data.get("description") or "")[:3000],
            "details": data.get("details") if isinstance(data.get("details"), dict) else {},
            "photos": safe_photos,
            "photos_count": len(photos),
        }
    })


@app.get("/api/admin/moderation/<int:request_id>/photo/<int:photo_index>")
def mini_app_admin_moderation_photo(request_id, photo_index):
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(user):
        return jsonify({"error":"admin_only"}), 403
    item = dict(load_pending_moderation_queue()).get(int(request_id))
    if not isinstance(item, dict):
        return jsonify({"error":"request_not_found"}), 404
    data = item.get("data") if isinstance(item.get("data"), dict) else {}
    photos = data.get("photos") or []
    if not isinstance(photos, list) or photo_index < 0 or photo_index >= min(len(photos), 8):
        return jsonify({"error":"photo_not_found"}), 404
    photo_ref = photos[photo_index]
    if not isinstance(photo_ref, str) or not photo_ref.strip():
        return jsonify({"error":"photo_not_found"}), 404

    try:
        # New Mini App uploads are Supabase Storage URLs; legacy listings keep
        # Telegram file_id values. Resolve each format without changing stored data.
        storage_object = _storage_object_from_url(photo_ref)
        if storage_object:
            parsed_url = urllib.parse.urlparse(photo_ref)
            supabase_url = urllib.parse.urlparse(SUPABASE_URL or "")
            if (
                parsed_url.scheme != "https"
                or not parsed_url.hostname
                or not supabase_url.hostname
                or parsed_url.hostname.lower() != supabase_url.hostname.lower()
                or parsed_url.username is not None
                or parsed_url.password is not None
                or parsed_url.port not in (None, 443)
            ):
                return jsonify({"error":"photo_not_found"}), 404
            image_response = HTTP_SESSION.get(
                photo_ref, timeout=(5, 25), allow_redirects=False
            )
            if 300 <= image_response.status_code < 400:
                image_response.close()
                return jsonify({"error":"photo_not_found"}), 404
            image_response.raise_for_status()
            source_label = "Supabase Storage"
            file_path = storage_object[1]
        else:
            # Legacy Telegram file_id path. Keep this unchanged for existing ads.
            file_info = api("getFile", {"file_id": photo_ref})
            if not isinstance(file_info, dict) or not file_info.get("ok"):
                description = str((file_info or {}).get("description") or "getFile failed")[:180]
                print("ADMIN MODERATION GETFILE ERROR:", request_id, photo_index, description)
                return jsonify({"error":"telegram_file_unavailable","message":description}), 502
            file_path = (file_info.get("result") or {}).get("file_path")
            if not file_path or ".." in str(file_path).split("/"):
                return jsonify({"error":"telegram_file_unavailable"}), 502
            image_response = HTTP_SESSION.get(
                f"https://api.telegram.org/file/bot{BOT_TOKEN}/{file_path}",
                timeout=(5, 25), allow_redirects=False
            )
            image_response.raise_for_status()
            source_label = "Telegram"

        # Trust actual image signatures because upstreams may return
        # application/octet-stream for valid image bytes.
        image_bytes = image_response.content
        if image_bytes.startswith(b"\xff\xd8\xff"):
            content_type = "image/jpeg"
        elif image_bytes.startswith(b"\x89PNG\r\n\x1a\n"):
            content_type = "image/png"
        elif image_bytes.startswith((b"GIF87a", b"GIF89a")):
            content_type = "image/gif"
        elif len(image_bytes) >= 12 and image_bytes[:4] == b"RIFF" and image_bytes[8:12] == b"WEBP":
            content_type = "image/webp"
        else:
            reported_type = image_response.headers.get("Content-Type", "unknown").split(";")[0].strip().lower()
            if reported_type.startswith("image/"):
                content_type = reported_type
            else:
                diagnostic = {
                    "source": source_label,
                    "content_type": reported_type,
                    "bytes": len(image_bytes),
                    "signature": image_bytes[:24].hex(),
                    "file_extension": str(file_path).rsplit(".", 1)[-1].lower()[:12] if "." in str(file_path) else "",
                }
                print("ADMIN MODERATION INVALID PHOTO:", request_id, photo_index, diagnostic)
                return jsonify({
                    "error":"invalid_photo_type",
                    "message":f"Файл из {source_label} не распознан как изображение.",
                    "diagnostic":diagnostic,
                }), 502
        return Response(
            image_bytes,
            status=200,
            mimetype=content_type,
            headers={
                "Cache-Control":"private, max-age=300",
                "X-Content-Type-Options":"nosniff",
                "Content-Length":str(len(image_bytes)),
            },
        )
    except (requests.RequestException, ValueError) as error:
        print("ADMIN MODERATION PHOTO ERROR:", request_id, photo_index, repr(error))
        return jsonify({"error":"photo_download_failed","message":str(error)[:180]}), 502


@app.post("/api/admin/moderation/<int:request_id>/action")
def mini_app_admin_moderation_action(request_id):
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(user):
        return jsonify({"error":"admin_only"}), 403
    if not supabase_enabled():
        return jsonify({"error":"db_unavailable"}), 503
    rate_limit = _mm_rate_limit_guard("admin_moderation_action", user.get("id"), 30, 60)
    if rate_limit:
        return rate_limit
    body = request.get_json(silent=True) or {}
    action = str(body.get("action") or "").strip().lower()
    if action not in ("approve", "reject"):
        return jsonify({"error":"invalid_action"}), 400
    pending = dict(load_pending_moderation_queue())
    if int(request_id) not in pending:
        return jsonify({"error":"request_not_found"}), 404
    admin_id = user.get("id")
    try:
        admin_id = int(admin_id)
    except (TypeError, ValueError):
        return jsonify({"error":"invalid_admin"}), 403
    if action == "approve":
        moderate_publish(int(request_id), admin_id, None)
        still_pending = int(request_id) in dict(load_pending_moderation_queue())
        if still_pending:
            return jsonify({"error":"publish_failed","message":"Не удалось опубликовать. Заявка оставлена в очереди."}), 502
        return jsonify({"ok":True,"status":"published"})
    moderate_reject(int(request_id), admin_id, None)
    still_pending = int(request_id) in dict(load_pending_moderation_queue())
    if still_pending:
        return jsonify({"error":"reject_failed"}), 502
    return jsonify({"ok":True,"status":"rejected"})


@app.post("/api/admin/listing/<int:listing_id>/unpublish")
def mini_app_admin_unpublish_listing(listing_id):
    """Администратор снимает опубликованное объявление после подтверждения очистки Telegram."""
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(user):
        return jsonify({"error":"admin_only"}), 403
    if not supabase_enabled():
        return jsonify({"error":"db_unavailable"}), 503
    rate_limit = _mm_rate_limit_guard("admin_listing_unpublish", user.get("id"), 10, 60)
    if rate_limit:
        return rate_limit

    rows = supabase_request("GET", "listings", params={
        "select":"id,status,metadata,channel_url,channel_message_id,user_id",
        "id":f"eq.{int(listing_id)}", "limit":"1"
    })
    if rows is None:
        return jsonify({"error":"listing_lookup_failed"}), 503
    if not rows:
        return jsonify({"error":"listing_not_found"}), 404
    row = rows[0]
    status = str(row.get("status") or "").strip().lower()
    if status == "archived":
        return jsonify({"ok":True,"status":"archived","already_unpublished":True})
    if status != "published":
        return jsonify({"error":"invalid_status","status":status}), 409

    # If a channel URL exists but message IDs are missing, never claim the
    # Telegram post was removed; the administrator must resolve the link manually.
    metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
    known_ids = metadata.get("channel_message_ids") if isinstance(metadata, dict) else []
    has_message_ids = bool(row.get("channel_message_id") or (isinstance(known_ids, list) and known_ids))
    if row.get("channel_url") and not has_message_ids:
        return jsonify({
            "error":"channel_message_ids_missing",
            "message":"У объявления есть ссылка на Telegram, но нет ID сообщения. Статус не изменён, чтобы не скрыть неудалённый пост."
        }), 409

    # Keep database row and Telegram IDs unless Telegram confirms cleanup.
    if not _delete_listing_channel_messages(row):
        return jsonify({
            "error":"channel_cleanup_failed",
            "message":"Не удалось подтвердить удаление публикации из Telegram. Объявление оставлено без изменений; можно повторить попытку."
        }), 502

    updated = supabase_request(
        "PATCH", "listings",
        params={"id":f"eq.{int(listing_id)}","status":"eq.published"},
        payload={"status":"archived","channel_url":"","channel_message_id":None},
    )
    if not isinstance(updated, list) or not updated:
        return jsonify({
            "error":"db_update_failed",
            "message":"Пост удалён из Telegram, но статус в каталоге не обновлён. Повторное действие безопасно."
        }), 503
    _record_listing_status_change(listing_id, status, "archived", "admin_unpublish", "admin", user.get("id") or user.get("telegram_id") or user.get("user_id"))
    load_supabase_published_listings()
    return jsonify({"ok":True,"status":"archived"})


@app.post("/api/listing/<int:listing_id>/report")
def mini_app_submit_listing_report(listing_id):
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"ok":False,"error":"invalid_init_data"}), 401
    if not supabase_enabled():
        return jsonify({"ok":False,"error":"db_unavailable"}), 503
    rate_limit = _mm_rate_limit_guard("listing_report", user.get("id"), 5, 3600)
    if rate_limit:
        return rate_limit
    payload = request.get_json(silent=True) or {}
    reason = str(payload.get("reason") or "").strip().lower()
    allowed_reasons = {"scam", "false_information", "spam", "prohibited_item", "other"}
    if reason not in allowed_reasons:
        return jsonify({"ok":False,"error":"invalid_reason"}), 400
    details = str(payload.get("details") or "").strip()
    if len(details) > 1000:
        return jsonify({"ok":False,"error":"details_too_long"}), 400
    listing_rows = supabase_request("GET", "listings", params={
        "select":"id,user_id,title,status",
        "id":f"eq.{listing_id}", "status":"eq.published", "limit":"1"
    })
    if not isinstance(listing_rows, list) or not listing_rows:
        return jsonify({"ok":False,"error":"listing_not_found"}), 404
    reporter_id = _supabase_user_id(user.get("id"))
    if not reporter_id:
        return jsonify({"ok":False,"error":"user_sync_failed"}), 503
    if str(listing_rows[0].get("user_id") or "") == str(reporter_id):
        return jsonify({"ok":False,"error":"cannot_report_own_listing"}), 400
    existing = supabase_request("GET", "mm_listing_reports", params={
        "select":"id", "listing_id":f"eq.{listing_id}",
        "reporter_user_id":f"eq.{reporter_id}", "status":"in.(new,reviewing)", "limit":"1"
    })
    if isinstance(existing, list) and existing:
        return jsonify({"ok":False,"error":"duplicate_active_report"}), 409
    inserted = supabase_request("POST", "mm_listing_reports", payload={
        "listing_id":listing_id,
        "listing_title":str(listing_rows[0].get("title") or "Объявление")[:500],
        "reporter_user_id":reporter_id,
        "reason":reason,
        "details":details or None,
        "status":"new"
    })
    if not isinstance(inserted, list) or not inserted:
        print("MADLOBA REPORT INSERT ERROR:", str(LAST_SUPABASE_ERROR)[:500])
        if "duplicate key" in str(LAST_SUPABASE_ERROR).lower():
            return jsonify({"ok":False,"error":"duplicate_active_report"}), 409
        return jsonify({
            "ok": False,
            "error": "report_save_failed",
            "detail": str(LAST_SUPABASE_ERROR or "Supabase returned no inserted row")[:500],
        }), 503
    return jsonify({"ok":True,"report_id":inserted[0].get("id")})


@app.post("/api/admin/support/<int:ticket_id>/action")
def mini_app_admin_support_action(ticket_id):
    admin = _mini_app_authenticated_user()
    if not admin:
        return jsonify({"ok":False,"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(admin):
        return jsonify({"ok":False,"error":"admin_only"}), 403
    if not supabase_enabled():
        return jsonify({"ok":False,"error":"db_unavailable"}), 503
    rate_limit = _mm_rate_limit_guard("admin_support_action", admin.get("id"), 30, 60)
    if rate_limit:
        return rate_limit
    payload = request.get_json(silent=True) or {}
    action = str(payload.get("action") or "").strip().lower()
    status_by_action = {"review":"in_progress", "close":"closed", "reopen":"new"}
    new_status = status_by_action.get(action)
    if not new_status:
        return jsonify({"ok":False,"error":"invalid_action"}), 400
    existing = supabase_request("GET", "mm_support_tickets", params={
        "select":"id,status", "id":f"eq.{ticket_id}", "limit":"1"
    })
    if not isinstance(existing, list) or not existing:
        return jsonify({"ok":False,"error":"support_ticket_not_found"}), 404
    updated = supabase_request("PATCH", "mm_support_tickets", params={"id":f"eq.{ticket_id}"}, payload={
        "status":new_status,
        "updated_at":_utc_now_iso(),
        "handled_by":str(admin.get("id") or admin.get("telegram_id") or admin.get("user_id") or "")
    })
    if not isinstance(updated, list) or not updated:
        return jsonify({"ok":False,"error":"support_ticket_update_failed"}), 503
    return jsonify({"ok":True,"status":new_status})


@app.post("/api/admin/report/<int:report_id>/action")
def mini_app_admin_report_action(report_id):
    admin = _mini_app_authenticated_user()
    if not admin:
        return jsonify({"ok":False,"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(admin):
        return jsonify({"ok":False,"error":"admin_only"}), 403
    if not supabase_enabled():
        return jsonify({"ok":False,"error":"db_unavailable"}), 503
    rate_limit = _mm_rate_limit_guard("admin_report_action", admin.get("id"), 30, 60)
    if rate_limit:
        return rate_limit
    payload = request.get_json(silent=True) or {}
    action = str(payload.get("action") or "").strip().lower()
    reports = supabase_request("GET", "mm_listing_reports", params={
        "select":"id,listing_id,status", "id":f"eq.{report_id}", "limit":"1"
    })
    if not isinstance(reports, list) or not reports:
        return jsonify({"ok":False,"error":"report_not_found"}), 404
    report = reports[0]
    if action == "review":
        updated = supabase_request("PATCH", "mm_listing_reports", params={"id":f"eq.{report_id}"}, payload={"status":"reviewing","updated_at":_utc_now_iso()})
    elif action == "dismiss":
        updated = supabase_request("PATCH", "mm_listing_reports", params={"id":f"eq.{report_id}"}, payload={"status":"dismissed","updated_at":_utc_now_iso()})
    elif action == "hide":
        listing_id = report.get("listing_id")
        if not listing_id:
            return jsonify({"ok":False,"error":"listing_already_missing"}), 409

        # Use the same Telegram cleanup rule as the dedicated admin unpublish
        # action. Never archive a published listing while its channel post may
        # still be visible. An already archived listing is safe to finalize.
        listing_rows = supabase_request("GET", "listings", params={
            "select":"id,status,metadata,channel_url,channel_message_id",
            "id":f"eq.{listing_id}", "limit":"1"
        })
        if listing_rows is None:
            return jsonify({"ok":False,"error":"listing_lookup_failed"}), 503
        if not listing_rows:
            return jsonify({"ok":False,"error":"listing_already_missing"}), 409
        listing = listing_rows[0]
        listing_status = str(listing.get("status") or "").strip().lower()

        if listing_status == "published":
            metadata = listing.get("metadata") if isinstance(listing.get("metadata"), dict) else {}
            known_ids = metadata.get("channel_message_ids") or []
            has_message_ids = bool(
                listing.get("channel_message_id")
                or (isinstance(known_ids, list) and known_ids)
            )
            if listing.get("channel_url") and not has_message_ids:
                return jsonify({
                    "ok":False,
                    "error":"channel_message_ids_missing",
                    "message":"У объявления есть ссылка на Telegram, но нет ID сообщения. Статус не изменён."
                }), 409
            if not _delete_listing_channel_messages(listing):
                return jsonify({
                    "ok":False,
                    "error":"channel_cleanup_failed",
                    "message":"Не удалось подтвердить удаление публикации из Telegram. Объявление не изменено; можно повторить попытку."
                }), 502
            hidden = supabase_request(
                "PATCH", "listings",
                params={"id":f"eq.{listing_id}","status":"eq.published"},
                payload={"status":"archived","updated_at":_utc_now_iso(),"channel_url":"","channel_message_id":None}
            )
            if not isinstance(hidden, list) or not hidden:
                return jsonify({"ok":False,"error":"listing_hide_failed","message":"Публикация удалена из Telegram, но статус объявления не обновлён. Повтори действие."}), 503
            _record_listing_status_change(listing_id, listing_status, "archived", "admin_hide_after_report", "admin", admin.get("id") or admin.get("telegram_id") or admin.get("user_id"))
        elif listing_status != "archived":
            return jsonify({"ok":False,"error":"listing_not_published","status":listing_status}), 409

        # Resolve the complaint only after the listing is confirmed archived.
        updated = supabase_request(
            "PATCH", "mm_listing_reports",
            params={"id":f"eq.{report_id}"},
            payload={"status":"resolved","updated_at":_utc_now_iso()}
        )
    else:
        return jsonify({"ok":False,"error":"invalid_action"}), 400
    if not isinstance(updated, list) or not updated:
        return jsonify({"ok":False,"error":"report_update_failed"}), 503
    return jsonify({"ok":True,"action":action})


