@app.post("/api/support")
def mini_app_support():
    """Forward a Mini App feedback message to configured Telegram administrators."""
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"ok": False, "error": "invalid_init_data"}), 401

    payload = request.get_json(silent=True) or {}
    message = str(payload.get("message") or "").strip()
    topic_key = str(payload.get("topic") or "other").strip().lower()
    topic_labels = {
        "question": "Вопрос", "listing": "Проблема с объявлением",
        "bug": "Ошибка в приложении", "idea": "Предложение", "other": "Другое",
    }
    if not message:
        return jsonify({"ok": False, "error": "empty_message"}), 400
    if len(message) > 2000:
        return jsonify({"ok": False, "error": "message_too_long"}), 400

    rate_limit = _mm_rate_limit_guard("support", user.get("id"), 3, 600)
    if rate_limit:
        return rate_limit

    if not supabase_enabled():
        return jsonify({"ok": False, "error": "db_unavailable"}), 503

    user_id = str(user.get("id") or "")
    full_name = " ".join(str(user.get(key) or "").strip() for key in ("first_name", "last_name")).strip()
    username = str(user.get("username") or "").strip()
    city_key = str(payload.get("city") or "batumi").lower()
    city_label = {"batumi": "Batumi", "tbilisi": "Tbilisi"}.get(city_key, "Не указан")
    topic = topic_labels.get(topic_key, topic_labels["other"])
    lang = str(payload.get("lang") or "ru").strip().lower()[:8]

    # Persist first: the admin panel reads this durable inbox, Telegram is only a notification.
    inserted = supabase_request("POST", "mm_support_tickets", payload={
        "telegram_user_id": user_id,
        "username": username or None,
        "full_name": full_name or None,
        "city": city_label,
        "lang": lang,
        "topic": topic_key if topic_key in topic_labels else "other",
        "message": message,
        "status": "new",
    })
    if not isinstance(inserted, list) or not inserted:
        print("MADLOBA SUPPORT SAVE ERROR:", str(LAST_SUPABASE_ERROR)[:500])
        return jsonify({"ok": False, "error": "support_save_failed"}), 503
    ticket_id = inserted[0].get("id")

    admin_ids = set(ADMIN_TELEGRAM_IDS)
    if str(ADMIN_CHAT_ID).strip().isdigit():
        admin_ids.add(str(ADMIN_CHAT_ID).strip())
    header = (
        "📩 <b>Обращение из MADLOBA MARKET</b>\n"
        f"<b>Обращение:</b> #{html.escape(str(ticket_id or '—'))}\n\n"
        f"<b>Тема:</b> {html.escape(topic)}\n"
        f"<b>Пользователь:</b> {html.escape(full_name or 'Telegram пользователь')}"
        + (f" (@{html.escape(username)})" if username else "") + "\n"
        f"<b>Telegram ID:</b> <code>{html.escape(user_id)}</code>\n"
        f"<b>Город:</b> {html.escape(city_label)}\n\n"
        f"<b>Сообщение:</b>\n{html.escape(message)}"
    )
    delivered = 0
    for admin_id in admin_ids:
        notification = {"chat_id": admin_id, "text": header, "parse_mode": "HTML", "disable_web_page_preview": True}
        if user_id.isdigit():
            notification["reply_markup"] = {"inline_keyboard": [[{"text": "💬 Ответить", "callback_data": f"support_reply_{user_id}"}]]}
        result = api("sendMessage", notification)
        if isinstance(result, dict) and result.get("ok"):
            delivered += 1
        else:
            print("MADLOBA SUPPORT DELIVERY ERROR:", admin_id, str(result)[:300])
    # The ticket is already safely stored. A Telegram notification failure must not
    # make the user resend the same message and create duplicate tickets.
    return jsonify({"ok": True, "ticket_id": ticket_id, "notification_delivered": bool(delivered)})


def _mini_app_owned_row(listing_id):
    """Возвращает объявление, если оно принадлежит текущему Telegram-пользователю."""
    if not supabase_enabled():
        return None, None, None
    user = _mini_app_authenticated_user()
    if not user:
        return None, None, None
    user_id = _supabase_user_id(user.get("id"))
    if not user_id:
        return None, user, None
    rows = supabase_request(
        "GET",
        "listings",
        params={
            "select":"id,user_id,title,description,price,currency,address,metadata,channel_url,channel_message_id,created_at,published_at,expires_at,reminder_sent_at,category_id,city_id,status,phone,whatsapp,telegram",
            "id":f"eq.{int(listing_id)}",
            "user_id":f"eq.{user_id}",
            "limit":"1",
        },
    )
    return (rows[0] if rows else None), user, user_id


def _delete_listing_channel_messages(row):
    """Удаляет связанные сообщения из канала; возвращает False, если удаление надо повторить."""
    ids = []
    metadata = row.get("metadata") or {}
    if isinstance(metadata, dict):
        raw = metadata.get("channel_message_ids") or []
        if isinstance(raw, list):
            ids.extend(raw)
    if row.get("channel_message_id"):
        ids.append(row.get("channel_message_id"))
    seen = set()
    normalized_ids = []
    for message_id in ids:
        try:
            message_id = int(message_id)
        except (TypeError, ValueError):
            continue
        if message_id not in seen:
            seen.add(message_id)
            normalized_ids.append(message_id)
    if not normalized_ids:
        return True
    listing_id = row.get("id")
    listing_status = row.get("status")
    metadata = dict(row.get("metadata") or {}) if isinstance(row.get("metadata"), dict) else {}
    manual_ids = metadata.get("channel_cleanup_manual_ids")
    if isinstance(manual_ids, list) and manual_ids:
        pending_ids = {int(x) for x in manual_ids if str(x).isdigit()}
        blocked_ids = [x for x in normalized_ids if x in pending_ids]
        if blocked_ids:
            print("LISTING LIFECYCLE: manual Telegram cleanup still required", {
                "listing_id": listing_id, "status": listing_status,
                "message_ids": blocked_ids, "action": "skipped_until_admin_confirmation",
            })
            return False
    if not CHANNEL_USERNAME:
        print("LISTING LIFECYCLE: Telegram cleanup blocked", {
            "listing_id": listing_id,
            "status": listing_status,
            "reason": "channel_username_missing",
            "message_ids": normalized_ids,
        })
        return False
    all_ok = True
    for message_id in normalized_ids:
        result = api("deleteMessage", {"chat_id": CHANNEL_USERNAME, "message_id": message_id})
        if isinstance(result, dict) and result.get("ok"):
            continue
        description_raw = result.get("description", "") if isinstance(result, dict) else str(result or "no_response")
        description = str(description_raw).lower()
        # Already-deleted messages are safe to treat as complete.
        if "message to delete not found" in description or "message identifier is not specified" in description:
            print("LISTING LIFECYCLE: Telegram post already absent", {
                "listing_id": listing_id, "message_id": message_id,
            })
            continue
        all_ok = False
        too_old = "message can't be deleted" in description or "message can not be deleted" in description
        if too_old:
            manual_ids = metadata.get("channel_cleanup_manual_ids")
            if not isinstance(manual_ids, list):
                manual_ids = []
            if message_id not in [int(x) for x in manual_ids if str(x).isdigit()]:
                manual_ids.append(message_id)
            metadata["channel_cleanup_manual_ids"] = manual_ids
            metadata["channel_cleanup_manual_reason"] = "telegram_message_delete_time_limit"
            metadata["channel_cleanup_manual_marked_at"] = _utc_now_iso()
            saved = supabase_request(
                "PATCH", "listings",
                params={"id":f"eq.{listing_id}"},
                payload={"metadata":metadata},
            )
            error_info = {
                "listing_id": listing_id, "status": listing_status,
                "message_id": message_id, "channel": CHANNEL_USERNAME,
                "error_code": result.get("error_code") if isinstance(result, dict) else None,
                "description": str(description_raw)[:200],
                "action": "manual_cleanup_required" if saved is not None else "manual_cleanup_marker_save_failed",
            }
        else:
            error_info = {
                "listing_id": listing_id, "status": listing_status,
                "message_id": message_id, "channel": CHANNEL_USERNAME,
                "error_code": result.get("error_code") if isinstance(result, dict) else None,
                "description": str(description_raw)[:200],
                "action": "kept_for_retry",
            }
        print("LISTING LIFECYCLE: Telegram delete failed", error_info)
    if all_ok:
        print("LISTING LIFECYCLE: Telegram cleanup complete", {
            "listing_id": listing_id, "message_ids": normalized_ids,
        })
    return all_ok


def _sync_edited_listing_to_channel(row, data):
    """Обновляет пост в Telegram и явно сообщает, если синхронизация не удалась."""
    if not CHANNEL_USERNAME or not row.get("channel_message_id"):
        return True
    try:
        text_value = build_listing(data)
        photos = data.get("photos") or []
        if photos:
            result = api("editMessageCaption", {
                "chat_id": CHANNEL_USERNAME,
                "message_id": row.get("channel_message_id"),
                "caption": text_value,
                "parse_mode": "HTML",
            })
        else:
            result = api("editMessageText", {
                "chat_id": CHANNEL_USERNAME,
                "message_id": row.get("channel_message_id"),
                "text": text_value,
                "parse_mode": "HTML",
            })
        if isinstance(result, dict) and result.get("ok") is True:
            return True
        description = str(result.get("description", "") if isinstance(result, dict) else result or "no_response")
        # Telegram may reject an identical edit; the desired state is already present.
        if "message is not modified" in description.lower():
            return True
        print("MINI APP CHANNEL SYNC ERROR:", {
            "listing_id": row.get("id"),
            "message_id": row.get("channel_message_id"),
            "description": description[:200],
        })
        return False
    except Exception as error:
        print("MINI APP CHANNEL SYNC ERROR:", repr(error))
        return False


@app.post("/api/admin/listing/<int:listing_id>/confirm-manual-cleanup")
def mini_app_admin_confirm_manual_cleanup(listing_id):
    """Finalize expiry only after an administrator manually removes the old channel post."""
    admin = _mini_app_authenticated_user()
    if not admin:
        return jsonify({"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(admin):
        return jsonify({"error":"admin_only"}), 403
    if not supabase_enabled():
        return jsonify({"error":"db_unavailable"}), 503
    rate_limit = _mm_rate_limit_guard("admin_confirm_manual_cleanup", admin.get("id"), 5, 600)
    if rate_limit:
        return rate_limit
    rows = supabase_request("GET", "listings", params={
        "select":"id,status,metadata,expires_at", "id":f"eq.{int(listing_id)}", "limit":"1"
    })
    if rows is None:
        return jsonify({"error":"listing_lookup_failed"}), 503
    if not rows:
        return jsonify({"error":"listing_not_found"}), 404
    row = rows[0]
    metadata = dict(row.get("metadata") or {}) if isinstance(row.get("metadata"), dict) else {}
    manual_ids = metadata.get("channel_cleanup_manual_ids")
    if not isinstance(manual_ids, list) or not manual_ids:
        return jsonify({"error":"manual_cleanup_not_required"}), 409
    # This endpoint is only called after the admin has manually deleted every listed post.
    metadata.pop("channel_cleanup_manual_ids", None)
    metadata.pop("channel_cleanup_manual_reason", None)
    metadata.pop("channel_cleanup_manual_marked_at", None)
    # The admin confirms that every ID in this list was manually removed.
    # Clear the historical Telegram IDs so the later purge does not retry them.
    metadata.pop("channel_message_ids", None)
    status = str(row.get("status") or "").lower()
    payload = {"metadata":metadata}
    if status == "published" and row.get("expires_at") and str(row.get("expires_at")) <= _utc_now_iso():
        payload.update({"status":"archived", "channel_url":"", "channel_message_id":None})
    updated = supabase_request("PATCH", "listings", params={
        "id":f"eq.{int(listing_id)}", "status":f"eq.{status}"
    }, payload=payload)
    if not isinstance(updated, list) or not updated:
        return jsonify({"error":"db_update_failed"}), 503
    if payload.get("status") != status:
        _record_listing_status_change(listing_id, status, payload.get("status"), "expiry_manual_telegram_cleanup_confirmed", "admin", admin.get("id") or admin.get("telegram_id") or admin.get("user_id"))
    print("LISTING LIFECYCLE: manual Telegram cleanup confirmed", {
        "listing_id":int(listing_id), "manually_removed_message_ids":manual_ids,
        "new_status":payload.get("status", status),
    })
    return jsonify({"ok":True,"status":payload.get("status", status)})


@app.post("/api/admin/listing/<int:listing_id>/restore")
def mini_app_admin_restore_listing(listing_id):
    """Администратор возвращает архивное объявление в каталог и Telegram без дубля."""
    admin = _mini_app_authenticated_user()
    if not admin:
        return jsonify({"error":"invalid_init_data"}), 401
    if not _is_admin_telegram_user(admin):
        return jsonify({"error":"admin_only"}), 403
    if not supabase_enabled():
        return jsonify({"error":"db_unavailable"}), 503
    rate_limit = _mm_rate_limit_guard("admin_listing_restore", admin.get("id"), 5, 600)
    if rate_limit:
        return rate_limit

    rows = supabase_request("GET", "listings", params={
        "select":"*", "id":f"eq.{int(listing_id)}", "limit":"1"
    })
    if rows is None:
        return jsonify({"error":"listing_lookup_failed"}), 503
    if not rows:
        return jsonify({"error":"listing_not_found"}), 404
    row = rows[0]
    status = str(row.get("status") or "").strip().lower()
    if status == "published":
        return jsonify({"ok":True,"status":"published","already_published":True})
    if status != "archived":
        return jsonify({"error":"invalid_status","status":status}), 409

    # Atomic lock shared with owner republishing prevents two simultaneous posts.
    lock_time = _utc_now_iso()
    lock_params = {"id":f"eq.{int(listing_id)}", "status":"eq.archived"}
    claimed = supabase_request("PATCH", "listings", params={
        **lock_params, "republish_lock_at":"is.null"
    }, payload={"republish_lock_at":lock_time})
    if claimed is None:
        return jsonify({"error":"db_update_failed"}), 503
    if not claimed:
        stale_before = (datetime.now(timezone.utc)-timedelta(minutes=5)).isoformat()
        claimed = supabase_request("PATCH", "listings", params={
            **lock_params, "republish_lock_at":f"lt.{stale_before}"
        }, payload={"republish_lock_at":lock_time})
        if claimed is None:
            return jsonify({"error":"db_update_failed"}), 503
    if not claimed:
        return jsonify({"error":"republish_in_progress"}), 409

    def release_lock():
        supabase_request("PATCH", "listings", params={
            "id":f"eq.{int(listing_id)}", "status":"eq.archived",
            "republish_lock_at":f"eq.{lock_time}"
        }, payload={"republish_lock_at":None})

    metadata = dict(row.get("metadata") or {}) if isinstance(row.get("metadata"), dict) else {}
    data = dict(metadata)
    data["id"] = row.get("id")
    data["description"] = row.get("description") or metadata.get("description") or ""
    data["price"] = str(row.get("price")) if row.get("price") is not None else metadata.get("price", "")
    data["currency"] = row.get("currency") or metadata.get("currency") or "USD"
    data["district"] = row.get("address") or metadata.get("district") or ""
    data["contact"] = row.get("phone") or metadata.get("contact") or ""
    data["whatsapp"] = metadata.get("whatsapp") or ""
    data["telegram"] = metadata.get("telegram") or ""
    data["category_key"] = str(metadata.get("category_key") or "").strip()
    data["category"] = str(metadata.get("category") or "").strip()
    data["type"] = str(metadata.get("type") or "").strip()
    data["subcategory"] = str(metadata.get("subcategory") or "").strip()
    data["subcategory_key"] = str(metadata.get("subcategory_key") or "").strip()
    data["details"] = metadata.get("details") if isinstance(metadata.get("details"), dict) else {}
    if not data["category_key"] or not data["category"] or not data["type"]:
        release_lock()
        return jsonify({"error":"listing_data_incomplete"}), 409

    photo_rows = supabase_request("GET", "listing_photos", params={
        "select":"photo_url,sort_order", "listing_id":f"eq.{int(listing_id)}",
        "order":"sort_order.asc", "limit":"100"
    })
    if photo_rows is None:
        release_lock()
        return jsonify({"error":"photos_lookup_failed"}), 503
    data["photos"] = [str(x.get("photo_url")) for x in photo_rows if x.get("photo_url")]

    try:
        result = publish_listing(data)
    except Exception as exc:
        print("ADMIN RESTORE ERROR:", type(exc).__name__)
        release_lock()
        return jsonify({"error":"channel_publish_failed"}), 503
    if not result or not result.get("ok"):
        print("ADMIN RESTORE ERROR:", result)
        release_lock()
        return jsonify({"error":"channel_publish_failed"}), 503

    tg_result = result.get("result") if isinstance(result, dict) else None
    message_id = None
    if isinstance(tg_result, list) and tg_result:
        message_id = tg_result[0].get("message_id")
    elif isinstance(tg_result, dict):
        message_id = tg_result.get("message_id")
    channel_url = f"https://t.me/{CHANNEL_USERNAME[1:]}/{message_id}" if CHANNEL_USERNAME.startswith("@") and message_id else ""

    # Refresh the listing lifetime on admin restoration. Preserve the original
    # database row, photos, owner and attributes; only publication state changes.
    new_metadata = dict(metadata)
    new_metadata.pop("channel_message_ids", None)
    updated = supabase_request("PATCH", "listings", params={
        "id":f"eq.{int(listing_id)}", "status":"eq.archived",
        "republish_lock_at":f"eq.{lock_time}"
    }, payload={
        "status":"published", "published_at":_utc_now_iso(),
        "expires_at":(datetime.now(timezone.utc)+timedelta(days=10)).isoformat(),
        "reminder_sent_at":None, "reminder_3_sent_at":None,
        "reminder_2_sent_at":None, "reminder_1_sent_at":None,
        "channel_url":channel_url, "channel_message_id":message_id,
        "metadata":new_metadata, "republish_lock_at":None
    })
    if not isinstance(updated, list) or not updated:
        if message_id and CHANNEL_USERNAME:
            try:
                api("deleteMessage", {"chat_id":CHANNEL_USERNAME,"message_id":message_id})
            except Exception:
                pass
        release_lock()
        return jsonify({"error":"db_update_failed"}), 503

    _record_listing_status_change(listing_id, "archived", "published", "admin_restore", "admin", admin.get("id") or admin.get("telegram_id") or admin.get("user_id"))
    load_supabase_published_listings()
    return jsonify({"ok":True,"status":"published","channel_url":channel_url})


@app.post("/api/client-detail-perf")
def mini_app_client_detail_perf():
    # Диагностика только для авторизованных Telegram Mini App пользователей.
    if not _mini_app_authenticated_user():
        return jsonify({"error": "invalid_init_data"}), 401
    data = request.get_json(silent=True) or {}
    if not isinstance(data, dict):
        return jsonify({"error": "invalid_payload"}), 400
    try:
        listing_id = int(data.get("id", 0))
        metrics = {k: int(data.get(k, -1)) for k in ("network_ms", "parse_ms", "render_ms", "total_ms")}
    except (TypeError, ValueError, OverflowError):
        return jsonify({"error": "invalid_payload"}), 400
    if not (0 < listing_id < 1000000000 and all(0 <= v <= 120000 for v in metrics.values())):
        return jsonify({"error": "invalid_payload"}), 400
    print("PERF client_detail id={} network_ms={} parse_ms={} render_ms={} total_ms={}".format(
        listing_id, metrics["network_ms"], metrics["parse_ms"], metrics["render_ms"], metrics["total_ms"]), flush=True)
    return ("", 204)


@app.get("/api/my-listing/<int:listing_id>")
def mini_app_my_listing(listing_id):
    _perf_start = time.perf_counter()
    row, user, user_id = _mini_app_owned_row(listing_id)
    _perf_lookup = time.perf_counter()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    if not row:
        return jsonify({"error":"not_found"}), 404
    item = _attach_catalog_photos([row])[0]
    _perf_photos = time.perf_counter()
    item["title"] = row.get("title") or item.get("title") or listing_title(item)
    item["description"] = row.get("description") or item.get("description") or ""
    item["price"] = str(row.get("price")) if row.get("price") is not None else item.get("price", "")
    item["currency"] = row.get("currency") or item.get("currency", "")
    item["address"] = row.get("address") or item.get("district", "")
    row_metadata_for_district = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
    item["district_key"] = str(row_metadata_for_district.get("district_key") or "")
    item["phone"] = row.get("phone") or ""
    # WhatsApp/Telegram в Supabase могут быть boolean-полями.
    # Для Mini App берём пользовательские контакты из metadata,
    # где они хранятся как строки.
    row_metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
    item["whatsapp"] = row_metadata.get("whatsapp", "")
    item["telegram"] = row_metadata.get("telegram", "")
    item["status"] = row.get("status") or "draft"
    item["category_name"] = item.get("category") or "Объявление"
    owner_name = " ".join(str(user.get(k) or "").strip() for k in ("first_name", "last_name")).strip()
    item["seller"] = {"id": int(row.get("user_id") or user_id), "name": owner_name or None}
    print(f"PERF owner_detail id={listing_id} lookup_ms={(_perf_lookup-_perf_start)*1000:.1f} photos_ms={(_perf_photos-_perf_lookup)*1000:.1f} total_ms={(time.perf_counter()-_perf_start)*1000:.1f}", flush=True)
    return jsonify(item)


@app.patch("/api/my-listing/<int:listing_id>")
def mini_app_update_listing(listing_id):
    row, user, user_id = _mini_app_owned_row(listing_id)
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    rate_limit = _mm_rate_limit_guard("owner_listing_edit", user.get("id"), 10, 60)
    if rate_limit:
        return rate_limit
    if not row:
        return jsonify({"error":"not_found"}), 404
    payload = request.get_json(silent=True) or {}
    description = str(payload.get("description", "")).strip()[:5000]
    address = str(payload.get("address", "")).strip()[:300]
    phone = str(payload.get("phone", "")).strip()[:80]
    # Enforce the same Georgian mobile format on the server as in the Mini App UI.
    # The client-side check is for convenience; this check also protects direct API calls.
    compact_phone = re.sub(r"[\s()\-]", "", phone)
    if compact_phone and not re.fullmatch(r"\+9955\d{8}", compact_phone):
        return jsonify({"error":"invalid_phone","detail":"Телефон должен быть в формате +995 и ещё 9 цифр."}), 400
    phone = compact_phone
    whatsapp = str(payload.get("whatsapp", "")).strip()[:80]
    telegram = str(payload.get("telegram", "")).strip()[:80]
    currency = str(payload.get("currency", row.get("currency") or "USD")).upper().strip()
    if currency not in {"USD", "GEL"}:
        return jsonify({"error":"invalid_currency"}), 400
    raw_price = str(payload.get("price", "")).strip().replace(",", ".")
    price = None
    if raw_price:
        try:
            price = float(raw_price)
        except ValueError:
            return jsonify({"error":"invalid_price"}), 400
        if price < 0 or price > 100000000:
            return jsonify({"error":"invalid_price"}), 400

    metadata = dict(row.get("metadata") or {}) if isinstance(row.get("metadata"), dict) else {}
    metadata["description"] = description
    metadata["district"] = address
    if "district_key" in payload:
        district_key = str(payload.get("district_key") or "").strip().lower()
        valid_district_keys = {key for key, _label in realestate_districts_for_data(metadata)}
        if district_key and district_key not in valid_district_keys:
            return jsonify({"error":"invalid_district"}), 400
        metadata["district_key"] = district_key or None
    metadata["contact"] = phone
    metadata["whatsapp"] = whatsapp
    metadata["telegram"] = telegram
    metadata["currency"] = currency
    metadata["price"] = raw_price
    metadata.pop("_telegram_id", None)

    # Повторно ограничиваем UPDATE владельцем на уровне БД.
    # Это защита от гонок между проверкой владения и изменением записи.
    update_payload = {
        "description": description,
        "price": price,
        "currency": currency,
        "phone": phone,
        "address": address,
        "metadata": metadata,
    }

    updated = supabase_request(
        "PATCH",
        "listings",
        params={"id":f"eq.{listing_id}","user_id":f"eq.{user_id}"},
        payload=update_payload,
    )

    # Если старые данные metadata мешают PATCH, повторяем только
    # по основным колонкам. Само объявление при этом всё равно
    # обновляется, а расширенные данные останутся в текущем metadata.
    if updated is None:
        core_payload = dict(update_payload)
        core_payload.pop("metadata", None)
        updated = supabase_request(
            "PATCH",
            "listings",
            params={"id":f"eq.{listing_id}","user_id":f"eq.{user_id}"},
            payload=core_payload,
        )

    if updated is None:
        # Секрет Supabase сюда никогда не попадает; возвращаем только статус/текст ошибки.
        return jsonify({
            "error":"db_update_failed",
            "detail": LAST_SUPABASE_ERROR or "Supabase отклонил UPDATE",
        }), 503

    # metadata обновляем отдельным запросом только если основной
    # UPDATE прошёл без него. Это защищает редактирование от проблем
    # с JSONB/старыми metadata в конкретной записи.
    if "metadata" not in (updated[0] if isinstance(updated, list) and updated else {}):
        metadata_result = supabase_request(
            "PATCH",
            "listings",
            params={"id":f"eq.{listing_id}","user_id":f"eq.{user_id}"},
            payload={"metadata": metadata},
        )
        if metadata_result is None:
            print("MINI APP: metadata update skipped after successful core update")

    # Синхронизируем уже опубликованный текст с каналом.
    if str(row.get("status") or "").lower() == "published":
        edited = dict(metadata)
        edited["category_key"] = edited.get("category_key") or ""
        edited["details"] = dict(edited.get("details") or {})
        edited["photos"] = list(edited.get("photos") or [])
        edited["category"] = edited.get("category") or "Объявление"
        edited["type"] = edited.get("type") or ""
        edited["subcategory"] = edited.get("subcategory") or ""
        edited["description"] = description
        edited["district"] = address
        edited["contact"] = phone
        edited["whatsapp"] = whatsapp
        edited["telegram"] = telegram
        edited["currency"] = currency
        edited["price"] = raw_price
        if not _sync_edited_listing_to_channel(row, edited):
            return jsonify({
                "error":"channel_sync_failed",
                "detail":"Объявление сохранено, но не удалось обновить публикацию в Telegram. Повторите сохранение.",
            }), 502

    return jsonify({"ok":True})


@app.post("/api/my-listing/<int:listing_id>/unpublish")
def mini_app_unpublish_listing(listing_id):
    row, user, user_id = _mini_app_owned_row(listing_id)
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    rate_limit = _mm_rate_limit_guard("owner_listing_unpublish", user.get("id"), 10, 60)
    if rate_limit:
        return rate_limit
    if not row:
        return jsonify({"error":"not_found"}), 404
    status = str(row.get("status") or "").lower()
    if status != "published":
        return jsonify({"ok":True})
    # Do not mark the listing archived if Telegram cleanup failed. The owner can
    # retry; already-deleted messages are treated as complete by the helper.
    if not _delete_listing_channel_messages(row):
        return jsonify({"error":"channel_cleanup_failed"}), 502
    updated = supabase_request(
        "PATCH",
        "listings",
        params={"id":f"eq.{listing_id}","user_id":f"eq.{user_id}"},
        payload={"status":"archived","channel_url":"","channel_message_id":None},
    )
    if updated is None:
        return jsonify({"error":"db_update_failed"}), 503
    _record_listing_status_change(listing_id, status, "archived", "owner_unpublish", "owner", user.get("id") or user.get("telegram_id") or user.get("user_id"))
    return jsonify({"ok":True})


@app.post("/api/my-listing/<int:listing_id>/republish")
def mini_app_republish_listing(listing_id):
    """Возвращает снятое объявление в канал и каталог без создания дубля в БД."""
    row, user, user_id = _mini_app_owned_row(listing_id)
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    rate_limit = _mm_rate_limit_guard("owner_listing_republish", user.get("id"), 3, 600)
    if rate_limit:
        return rate_limit
    if not row:
        return jsonify({"error":"not_found"}), 404
    status = str(row.get("status") or "").lower()
    if status == "published":
        # The reminder button is shown before expiry, while the listing is still
        # published. Renew by adding 10 days to its current expiry (not silently
        # returning success without changing the date).
        now_utc = datetime.now(timezone.utc)
        raw_expiry = row.get("expires_at")
        if raw_expiry:
            try:
                expiry_dt = datetime.fromisoformat(str(raw_expiry).replace("Z", "+00:00"))
                if expiry_dt.tzinfo is None:
                    expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
            except (TypeError, ValueError):
                return jsonify({"error":"invalid_expiry"}), 409
            renewal_base = max(expiry_dt, now_utc)
        else:
            renewal_base = now_utc
        new_expiry = (renewal_base + timedelta(days=10)).isoformat()
        renewed = supabase_request(
            "PATCH", "listings",
            params={"id":f"eq.{int(listing_id)}", "user_id":f"eq.{user_id}", "status":"eq.published"},
            payload={"expires_at":new_expiry, "reminder_sent_at":None, "reminder_3_sent_at":None, "reminder_2_sent_at":None, "reminder_1_sent_at":None},
        )
        if renewed is None:
            return jsonify({"error":"db_update_failed"}), 503
        load_supabase_published_listings()
        return jsonify({"ok":True, "expires_at":new_expiry, "renewed":True})
    if status != "archived":
        return jsonify({"error":"not_republishable"}), 400

    # Expired listings can be renewed during the two-day grace period only.
    raw_expiry = row.get("expires_at")
    if raw_expiry:
        try:
            expiry_dt = datetime.fromisoformat(str(raw_expiry).replace("Z", "+00:00"))
            if expiry_dt.tzinfo is None:
                expiry_dt = expiry_dt.replace(tzinfo=timezone.utc)
            if expiry_dt <= datetime.now(timezone.utc) - timedelta(days=2):
                return jsonify({"error":"renewal_window_closed"}), 410
        except (TypeError, ValueError):
            return jsonify({"error":"invalid_expiry"}), 409

    # Atomic claim: only one request may republish an archived listing at a time.
    # The DB column is added by the companion SQL migration. A stale lock can be
    # reclaimed after five minutes if a worker crashed mid-publication.
    lock_time = _utc_now_iso()
    lock_params = {
        "id": f"eq.{int(listing_id)}",
        "user_id": f"eq.{user_id}",
        "status": "eq.archived",
    }
    claimed = supabase_request(
        "PATCH", "listings",
        params={**lock_params, "republish_lock_at": "is.null"},
        payload={"republish_lock_at": lock_time},
    )
    if claimed is None:
        return jsonify({"error":"db_update_failed"}), 503
    if not claimed:
        stale_before = (datetime.now(timezone.utc) - timedelta(minutes=5)).isoformat()
        claimed = supabase_request(
            "PATCH", "listings",
            params={**lock_params, "republish_lock_at": f"lt.{stale_before}"},
            payload={"republish_lock_at": lock_time},
        )
        if claimed is None:
            return jsonify({"error":"db_update_failed"}), 503
    if not claimed:
        return jsonify({"error":"republish_in_progress"}), 409

    def _release_republish_lock():
        supabase_request(
            "PATCH", "listings",
            params={
                "id": f"eq.{int(listing_id)}",
                "user_id": f"eq.{user_id}",
                "republish_lock_at": f"eq.{lock_time}",
            },
            payload={"republish_lock_at": None},
        )

    metadata = dict(row.get("metadata") or {}) if isinstance(row.get("metadata"), dict) else {}
    data = dict(metadata)
    data["id"] = row.get("id")
    data["description"] = row.get("description") or metadata.get("description") or ""
    data["price"] = str(row.get("price")) if row.get("price") is not None else metadata.get("price", "")
    data["currency"] = row.get("currency") or metadata.get("currency") or "USD"
    data["district"] = row.get("address") or metadata.get("district") or ""
    data["contact"] = row.get("phone") or metadata.get("contact") or ""
    data["whatsapp"] = metadata.get("whatsapp") or ""
    data["telegram"] = metadata.get("telegram") or ""

    # Rebuild only the expected presentation fields from persisted metadata.
    # Synthetic lifecycle-test rows contain no real category/details and must
    # never be sent to the public Telegram channel.
    data["category_key"] = str(metadata.get("category_key") or "").strip()
    data["category"] = str(metadata.get("category") or "").strip()
    data["type"] = str(metadata.get("type") or "").strip()
    data["subcategory"] = str(metadata.get("subcategory") or "").strip()
    data["subcategory_key"] = str(metadata.get("subcategory_key") or "").strip()
    data["details"] = metadata.get("details") if isinstance(metadata.get("details"), dict) else {}
    if not data["category_key"] or not data["category"] or not data["type"]:
        _release_republish_lock()
        print("MINI APP REPUBLISH ERROR: listing_data_incomplete", int(listing_id))
        return jsonify({"error":"listing_data_incomplete"}), 409

    photo_rows = supabase_request(
        "GET", "listing_photos",
        params={"select":"photo_url,sort_order", "listing_id":f"eq.{int(listing_id)}", "order":"sort_order.asc"},
    )
    if photo_rows is None:
        _release_republish_lock()
        print("MINI APP REPUBLISH ERROR: photo_lookup_failed", int(listing_id))
        return jsonify({"error":"photo_lookup_failed"}), 503
    data["photos"] = [str(x.get("photo_url")) for x in photo_rows if x.get("photo_url")]

    try:
        result = publish_listing(data)
    except Exception as exc:
        print("MINI APP REPUBLISH ERROR:", type(exc).__name__)
        _release_republish_lock()
        return jsonify({"error":"channel_publish_failed"}), 503
    if not result or not result.get("ok"):
        print("MINI APP REPUBLISH ERROR:", result)
        _release_republish_lock()
        return jsonify({"error":"channel_publish_failed"}), 503

    tg_result = result.get("result") if isinstance(result, dict) else None
    message_id = None
    if isinstance(tg_result, list) and tg_result:
        message_id = tg_result[0].get("message_id")
    elif isinstance(tg_result, dict):
        message_id = tg_result.get("message_id")

    channel_url = ""
    if CHANNEL_USERNAME.startswith("@") and message_id:
        channel_url = f"https://t.me/{CHANNEL_USERNAME[1:]}/{message_id}"

    updated = supabase_request(
        "PATCH", "listings",
        params={"id":f"eq.{int(listing_id)}", "user_id":f"eq.{user_id}", "status":"eq.archived", "republish_lock_at":f"eq.{lock_time}"},
        payload={"status":"published", "published_at":_utc_now_iso(), "expires_at":(datetime.now(timezone.utc) + timedelta(days=10)).isoformat(), "reminder_sent_at":None, "reminder_3_sent_at":None, "reminder_2_sent_at":None, "reminder_1_sent_at":None, "channel_url":channel_url, "channel_message_id":message_id, "republish_lock_at":None},
    )
    if updated is None:
        # Не оставляем новое сообщение в канале без связи с объявлением.
        if message_id and CHANNEL_USERNAME:
            try:
                api("deleteMessage", {"chat_id":CHANNEL_USERNAME, "message_id":message_id})
            except Exception:
                pass
        _release_republish_lock()
        return jsonify({"error":"db_update_failed"}), 503

    _record_listing_status_change(listing_id, "archived", "published", "owner_republish", "owner", user.get("id") or user.get("telegram_id") or user.get("user_id"))
    load_supabase_published_listings()
    return jsonify({"ok":True, "channel_url":channel_url})


@app.delete("/api/my-listing/<int:listing_id>")
def mini_app_delete_listing(listing_id):
    row, user, user_id = _mini_app_owned_row(listing_id)
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    rate_limit = _mm_rate_limit_guard("owner_listing_delete", user.get("id"), 3, 600)
    if rate_limit:
        return rate_limit
    if not row:
        return jsonify({"error":"not_found"}), 404
    # Keep the database row and photos until Telegram posts are confirmed deleted.
    # This preserves message IDs so a failed cleanup can be retried safely.
    if not _delete_listing_channel_messages(row):
        return jsonify({"error":"channel_cleanup_failed"}), 502
    photos_deleted = supabase_request(
        "DELETE",
        "listing_photos",
        params={"listing_id":f"eq.{listing_id}"},
    )
    if photos_deleted is None:
        return jsonify({"error":"db_photo_delete_failed"}), 503
    deleted = supabase_request(
        "DELETE",
        "listings",
        params={"id":f"eq.{listing_id}","user_id":f"eq.{user_id}"},
    )
    if deleted is None:
        return jsonify({"error":"db_delete_failed"}), 503
    if isinstance(deleted, list) and deleted:
        _record_listing_status_change(listing_id, row.get("status"), "deleted", "owner_permanent_delete", "owner", user.get("id") or user.get("telegram_id") or user.get("user_id"))
    return jsonify({"ok":True})


@app.get("/api/favorites")
def mini_app_favorites():
    if not supabase_enabled():
        return jsonify({"error":"db_unavailable"}), 503
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    user_id = _supabase_user_id(user.get("id"))
    if not user_id:
        return jsonify({"error":"user_not_found"}), 503

    cursor_raw = (request.args.get("cursor") or "").strip()
    cursor_created_at = None
    cursor_id = None
    if cursor_raw:
        try:
            if len(cursor_raw) > 512:
                raise ValueError("invalid cursor")
            padded = cursor_raw + "=" * (-len(cursor_raw) % 4)
            cursor_data = json.loads(base64.urlsafe_b64decode(padded.encode("ascii")).decode("utf-8"))
            cursor_created_at = str(cursor_data["created_at"])
            cursor_id = int(cursor_data["id"])
            parsed_cursor_time = datetime.fromisoformat(cursor_created_at.replace("Z", "+00:00"))
            if (not cursor_created_at or parsed_cursor_time.tzinfo is None or cursor_id <= 0
                    or cursor_id > 9223372036854775807 or len(cursor_created_at) > 64):
                raise ValueError("invalid cursor")
        except (ValueError, TypeError, KeyError, UnicodeError, json.JSONDecodeError):
            return jsonify({"error":"invalid_cursor"}), 400

    params = {
        "select":"listing_id,created_at,id",
        "user_id":f"eq.{user_id}",
        "order":"created_at.desc,id.desc",
        "limit":"31",
    }
    if cursor_created_at is not None:
        # Stable keyset pagination: timestamp first, bigint id as tie-breaker.
        params["or"] = f"(created_at.lt.{cursor_created_at},and(created_at.eq.{cursor_created_at},id.lt.{cursor_id}))"
    fav_rows = supabase_request("GET", "favorites", params=params)
    if fav_rows is None:
        return jsonify({"error":"db_unavailable"}), 503

    has_more = len(fav_rows) > 30
    page_favorites = fav_rows[:30]
    next_cursor = None
    if has_more and page_favorites:
        last = page_favorites[-1]
        token = json.dumps({"created_at":last.get("created_at"),"id":int(last["id"])}, separators=(",", ":"))
        next_cursor = base64.urlsafe_b64encode(token.encode("utf-8")).decode("ascii").rstrip("=")

    ids=[int(row["listing_id"]) for row in page_favorites if str(row.get("listing_id"," ")).isdigit()]
    if not ids:
        return jsonify({"items":[],"has_more":has_more,"next_cursor":next_cursor})
    rows = supabase_request(
        "GET",
        "listings",
        params={
            "select":"id,title,description,price,currency,price_usd,address,phone,metadata,channel_url,created_at,category_id,city_id,status",
            "id":f"in.({','.join(map(str,ids))})",
            "status":"eq.published",
            "expires_at": f"gt.{_utc_now_iso()}",
            "limit":"30",
        },
    )
    if rows is None:
        return jsonify({"error":"db_unavailable"}), 503
    by_id={int(row["id"]):row for row in rows if str(row.get("id"," ")).isdigit()}
    ordered=[by_id[i] for i in ids if i in by_id]
    items=_attach_catalog_photos(ordered)
    for idx,item in enumerate(items):
        row=ordered[idx]
        item["title"]=row.get("title") or item.get("title") or listing_title(item)
        item["description"]=row.get("description") or item.get("description") or ""
        item["price"]=str(row.get("price")) if row.get("price") is not None else item.get("price","")
        item["currency"]=row.get("currency") or item.get("currency","")
        item["address"]=row.get("address") or item.get("district","")
        item["category_name"]=item.get("category") or "Объявление"
        item["channel_post_url"]=row.get("channel_url") or ""
        item["is_favorite"]=True
        _strip_public_listing_fields(item)
        _strip_listing_contact_fields(item)
    return jsonify({"items":items,"has_more":has_more,"next_cursor":next_cursor,"usd_to_gel":_mm_usd_to_gel_display_rate()})


@app.post("/api/favorite/<int:listing_id>")
def mini_app_add_favorite(listing_id):
    if not supabase_enabled():
        return jsonify({"error":"db_unavailable"}), 503
    user = _mini_app_authenticated_user()
    if not user:
        return jsonify({"error":"invalid_init_data"}), 401
    user_id = _supabase_user_id(user.get("id"))
    if not user_id:
        return jsonify({"error":"user_not_found"}), 400
    rate_limit = _mm_rate_limit_guard("favorite_add", user.get("id"), 60, 60)
    if rate_limit:
        return rate_limit
    published = supabase_request(
        "GET","listings",
        params={"select":"id","id":f"eq.{listing_id}","status":"eq.published","expires_at":f"gt.{_utc_now_iso()}","limit":"1"},
    )
    if not published:
        return jsonify({"error":"listing_not_found"}), 404
    existing = supabase_request(
        "GET","favorites",
        params={"select":"id","user_id":f"eq.{user_id}","listing_id":f"eq.{listing_id}","limit":"1"},
    )
    if existing is None:
        return jsonify({"error":"db_unavailable"}), 503
    if existing:
        return jsonify({"ok":True,"favorite":True})
    created = supabase_request(
        "POST","favorites",
        payload={"user_id":user_id,"listing_id":listing_id},
    )
    if created is None:
        return jsonify({"error":"db_insert_failed"}), 503
    return jsonify({"ok":True,"favorite":True})


